# frozen_string_literal: true
require "rails_helper"

RSpec.describe Timekeeping::ReservationDerivation do
  it "gives two companies different operation ids for the same entry and invoice ids" do
    derive_for = lambda do |company_id|
      entry_row = Timekeeping::Handoff::Checkpoint::TABLES.fetch("entries").index_with { nil }
        .merge("id" => 1, "company_id" => company_id, "version" => 0, "duration" => 60.0, "locked" => true)
      described_class.derive(
        company_id:,
        entries: [{ id: 1, locked: true, company_id:, join_company_id: company_id, row: entry_row }],
        links: [{ entry_id: 1, invoice_id: 10, invoice_company_id: company_id, draft: false, discarded: false }],
        invoice_numbers: { 10 => "INV-1" },
        recorded_invoices: {},
        generation: 7,
        captured_at: Time.utc(2026, 10, 25, 12)
      )
    end

    # "a reservation's `operation_id` is a UUIDv5 of company, entry and invoice"
    first = derive_for.call(1)[:reservations].sole
    second = derive_for.call(2)[:reservations].sole

    expect(first["company_id"]).to eq(1)
    expect(second["company_id"]).to eq(2)
    expect(first["operation_id"]).not_to eq(second["operation_id"])
  end
end
